import * as React from 'react';
import Card from '@mui/material/Card';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import {Grid, Typography, Box} from '@mui/material';
import { CardActionArea } from '@mui/material';

function LocationsInfo (props){
    return (<React.Fragment>
                <Typography gutterBottom variant="subtitle2" component="h2" style={{fontWeight:'bold'}}>{props.sede.nombresede}</Typography>
                <Box sx={{lineHeight:0.05}}><Typography variant="caption">{props.sede.direccion1}<br/>{props.sede.direccion2}<br/>{props.sede.telefono1}</Typography></Box>
        </React.Fragment>);
}

function ActionAreaCard (props){
    const handleseleccion = (event)=>{
        const refclonada = Object.assign({}, props.nombre); //clonamos el objeto ubicación 'props.nombre' por que si pasamos directamente este objeto a la funcion de abajo, cunado modifiquemos las propiedades en el estado principal, se reflejará en las tarjetas
            props.manejaubicacion(refclonada);
    };
    return (
        <Card sx={{ maxWidth: 152, margin:'2px', border:'solid thin #CACDCE'}}>
            <CardActionArea onClick={handleseleccion}>
                <CardMedia
                component="img"
                height="80"
                image={`./images/${props.nombre.imagensede}`}
                alt={`${props.nombre.imagensede}`}
                />
                <CardContent sx={{padding:'5px'}}>
                    <LocationsInfo sede={props.nombre} />
                </CardContent>
            </CardActionArea>
        </Card>
    );
}


export default function MuestraUbicacionUsuario (props) {
    //filtramos las ubicaciones según logo nombre
    let listadoubicaciones = props.sedesMP.filter((elem)=>elem.logoname === props.logotipo);
    let ubicacionesfinal = listadoubicaciones.map((elem)=>(<ActionAreaCard nombre={elem} key={Math.random()} manejaubicacion={props.handleselectedubicacion} />));
    
    return (
        <React.Fragment>
            <Grid container item xs={12} spacing={1} sx={{marginLeft:'-2px'}}>
                {ubicacionesfinal}
            </Grid>
        </React.Fragment>
      );
  }