import * as React from 'react';
import { Grid, Fab, TextField } from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import SaveIcon from '@mui/icons-material/Save';

const inputProps = {
  step: 350,
};

class MuestraLocationAlternativa extends React.Component {
    constructor(props){
      super(props);
      this.handleChangeAlternativa = this.handleChangeAlternativa.bind(this);
      this.state = {
        back : false,
      };
    }
  
    handleChangeAlternativa = (event)=>{
      this.props.handleDirAlternativa(event.target);
    };
    handlebanderaBotonAdd = () => {
      this.setState((state, props) => {
                  return {back: !state.back};
                });
    }
  
    render(){
        return (
          <React.Fragment>
            <Grid container wrap='wrap' style={{backgroundColor:"#D7DCE5", padding:5, borderRadius:5, marginBottom:15, marginTop:10}}>
           
                <Grid item xs={3}>
                {!(this.state.back) ? 
                  <Fab variant="extended" size="small" aria-label="Add" sx={{backgroundColor:'#50718C', color:'#FFFFFF'}} onClick={this.handlebanderaBotonAdd}>
                    <EditIcon sx={{marginRight:0.8}}/> modify/new
                  </Fab>
                  :
                  <Fab variant="extended" size="small" aria-label="Add" sx={{backgroundColor:'#C33854', color:'#FFFFFF'}} onClick={this.handlebanderaBotonAdd}>
                    <SaveIcon sx={{marginRight:0.8}}/> save
                  </Fab>
                }
                </Grid>
                {(this.state.back) ?
                (<Grid item xs={9} style={{borderLeft:"solid thin #EEF0F4", paddingRight:5}}>
                  <TextField variant='standard' fullWidth style={{margin: 'auto 10px'}} margin="normal" id="dir1" name="direccion1" type="text" label="street, nº" value={this.props.usuario.office.direccion1} inputProps={inputProps} onChange={this.handleChangeAlternativa}></TextField>
                  <TextField variant='standard' fullWidth style={{margin: 'auto 10px'}} margin="normal" id="dir2" name="direccion2" type="text" label="P.O. city, Country" value={this.props.usuario.office.direccion2} inputProps={inputProps} onChange={this.handleChangeAlternativa}></TextField>
                  <TextField variant='standard' fullWidth style={{margin: 'auto 10px'}} margin="normal" id="ph1" name="telefono1" type="text" label="phone number" value={this.props.usuario.office.telefono1} inputProps={inputProps} onChange={this.handleChangeAlternativa}></TextField> 
                </Grid>):(null)}
    
            </Grid>
        </React.Fragment>
          );
      }
  }

  export default MuestraLocationAlternativa;