import * as React from 'react';
import Box from '@mui/material/Box';
import InputLabel from '@mui/material/InputLabel';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';

export default function BasicSelect(props) {
	const [domain, setDomain] = React.useState(props.idioma);

	const lista = props.listaseleccion.map((elem)=>
		<MenuItem value={elem['clave']} key={elem['clave']} >{elem['valor']}</MenuItem>
	);
  
	const handleChange = (event) => {
		setDomain(event.target.value);
		props.idiomaseleccionado(event.target.value);
	};
  
	return (
	  <Box sx={{ minWidth: 120 }}>
		<FormControl sx={{ m: 1, width: '100%', minWidth: 130, margin: '2px' }} size="small">
		  <InputLabel id="demo-simple-select-label">dominio/domain</InputLabel>
		  <Select
			labelId="demo-simple-select-label"
			id="demo-simple-select"
			value={domain}
			label="dominio/domain"
			onChange={handleChange}
		  >
		  {lista}
		  </Select>
		</FormControl>
	  </Box>
	);
  }