import React, { Component, useContext } from 'react';
import { styled } from '@mui/material/styles';
import { Container, Typography, Grid, Paper, Fab, Box} from '@mui/material';
import BarraMenu from './Componentes/BarraMenuCompany';
import Clipboard from "react-clipboard.js";
import Muestradatosusuario from './Componentes/MuestraDatosUsuario';
import MuestraUbicacionUsuario from './Componentes/MuestraUbicacionUsuario';
import MuestraLocationAlternativa from './Componentes/MuestraUbicacionAlternativa';
import TableSignature from './Componentes/TableSignature2023';
import Infotutorial from './Componentes/Infotutorial';
