const Item = styled(Paper)(({ theme }) => ({
  backgroundColor: theme.palette.mode === 'dark' ? '#1A2027' : '#fff',
  ...theme.typography.body2,
  paddingLeft: theme.spacing(5),
  paddingBotton: theme.spacing(5),
  textAlign: 'center',
  color: theme.palette.text.secondary,
}));

const Cabecera = styled(Typography)(({theme})=>({
  textAlign: 'center',
  color:'#C33854',
  padding: theme.spacing(1),
}));

function Imagenportada(props) {
  return (
    <Box style={{textAlign: 'left'}}>
      <img src={`./images/${props.logo}_w.svg`} alt="logo MP" height={props.altura}/>
    </Box>
  );
}

class App extends Component {
  constructor(props){
    super(props);
    this.state = {
      logosMP:[],
      sedesMP:[],
      redesMP:[],
      nombrelogo : 'logo',
      pathlogo : 'logo',
      username : '',
      surname : '',
      usermail : '',
      maildomain : '',
      nativejobtitle : '',
      englishjobtitle : '',
      mobilephone : '',
      extofficephone : '',
      office : null,
      webdomain : '',
      idioma:'en'
    };
    this.adaptaLogo = this.adaptaLogo.bind(this);
    this.adaptaDominio = this.adaptaDominio.bind(this);
    this.handleDatosPersonales = this.handleDatosPersonales.bind(this);
    this.handleDatosDominio = this.handleDatosDominio.bind(this);
    this.handleUbicacionSede = this.handleUbicacionSede.bind(this);
    this.handleUbicacionAlternativa = this.handleUbicacionAlternativa.bind(this);
  }

  adaptaLogo(nuevologo){
    let logoselected = this.state.logosMP.find((elem)=>nuevologo===elem.name)
    let {name,path,emaildomain,webdomain,defaultlang} = logoselected;
    this.setState({
      nombrelogo : name,
      pathlogo : path,
      idioma : defaultlang,
      office : null,
      maildomain : emaildomain[defaultlang],
      webdomain : webdomain[defaultlang]
    })
  }
  adaptaDominio(nuevodominio){
    this.setState({usermail : nuevodominio});
  }
  handleDatosPersonales(valor){
    this.setState({[valor.name] : valor.value})
  };
  handleDatosDominio(event){
    let businessselected = this.state.logosMP.find((elem)=>(elem.name === this.state.nombrelogo));
    let {emaildomain, webdomain} = businessselected;
    
    this.setState({
      idioma: event,
      webdomain: webdomain[event],
      maildomain: emaildomain[event]
    });

  };
  handleUbicacionSede(valor){
    this.setState({
      office : valor,
    });
  }
  handleUbicacionAlternativa(valor){
    this.setState((state,props)=>{
      const nuevadir = state.office;
      nuevadir[valor.name] = valor.value;
      return ({office : nuevadir});
    });
  }
 
  componentWillMount(){

    const urllogos = 'data/logosMP.json';
    const urlsedes = 'data/sedesMP.json';
    const urlredes = 'data/redesMP.json';

    fetch(urllogos,{
      headers : { 
        'Content-Type': 'application/json',
        'Accept': 'application/json'
       }})
      .then(response => response.json())
      .then(data => this.setState({logosMP:data}))
      .catch(error=>{
          console.log(error.message);
      });
    fetch(urlsedes,{
      headers : { 
        'Content-Type': 'application/json',
        'Accept': 'application/json'
       }})
        .then(response => response.json())
        .then(data => this.setState({sedesMP:data}))
        .catch(error=>{
            console.log(error.message);
        });
    fetch(urlredes,{
      headers : { 
        'Content-Type': 'application/json',
        'Accept': 'application/json'
       }})
        .then(response => response.json())
        .then(data => this.setState({redesMP:data}))
        .catch(error=>{
            console.log(error.message);
        });
       /*
      ESTE CÓDICO DE ABAJO SE UAS CON LA IMPORTACIÓN ESTÁTICA, POR LO QUE HAY QUE RECOMPILAR EL PROGRAMA CADA VEZ QUE SE CAMBIE LOS JSON
      ESTE CÓDIGO ES INCOMPATIBLE CON EL DE ARRIBA
     
      this.setState({
                      logosMP:logos,
                      sedesMP:sedes,
                      redesMP:redes
                    });
      */
  }
  
  render() {
    return (
      <div className="App">
      <Container maxWidth="lg" sx={{ padding:'0px 0px 25px 0px', backgroundColor:'#EFEFEF', marginTop:'0px', boxShadow: 3 }}>
        <Grid container spacing={2}>
          {/* MALLA HEADER */}
          <Grid item xs={12}>
            <Cabecera variant='h4'>Configura tu firma / Set up your signature</Cabecera>
          </Grid>
          <Grid item xs={12}>
            <BarraMenu logoseleccionado={this.adaptaLogo} listaseleccion={this.state.logosMP} keytoiterate="name" pathlogo={this.state.pathlogo}/>
          </Grid>
          {/* MALLA DE FORMULARIO DE ENTRADA DE DATOS */}
          <Grid item xs={12} sm={5}>
            {
              (this.state.nombrelogo !== 'logo') 
                ?<Muestradatosusuario logosMP={this.state.logosMP} logotipo={this.state.nombrelogo} idioma={this.state.idioma} modifDatosPersonales={this.handleDatosPersonales} modifDatosDominio={this.handleDatosDominio} />
                :<Imagenportada logo='principal' altura={316} />
            }

          {/* MALLA DE TARJETAS DE UBICACIONES DE SEDES POR EMPRESA */}

            {
              (this.state.nombrelogo !== 'logo')?(
                <Grid container wrap='wrap'>
                  <Grid item xs={12}>
                    {
                      (this.state.office!=null)
                      ?<MuestraLocationAlternativa usuario={this.state} handleDirAlternativa={this.handleUbicacionAlternativa}/>
                      :<Typography variant="h6" gutterBottom>Seleccione Centro de Trabajo / Select Job Centre: </Typography>
                    }
                  </Grid>
                  <Grid item xs={12}>
                    <MuestraUbicacionUsuario sedesMP={this.state.sedesMP} logotipo={this.state.nombrelogo} handleselectedubicacion={this.handleUbicacionSede}/>
                  </Grid>
              </Grid>
              ):(null)
            }
          </Grid>
          {/* MALLA DE SALIDA DE DATOS TABULADA == HTML OUTLOOK */}
          <Grid item xs={12} sm={7} textAlign='left'>
            
              {(this.state.nombrelogo !== 'logo')?(
                <React.Fragment>
                  <Item>
                    <TableSignature usuario={this.state} logo={this.state.pathlogo} />
                  </Item>
                  <Box sx={{height:10}} />
                  <Box sx={{textAlign:'center'}}>
                    <Clipboard component="a" button-href="#" data-clipboard-target="#copyfirma" class="clipboard">
                      <Fab variant="extended" size="small" aria-label="Add" sx={{backgroundColor:'#C33854', color:'#FFFFFF'}} onClick={this.handlebanderaBotonAdd}>
                        <SaveIcon sx={{marginRight:0.8}}/> Copy / Copiar
                      </Fab>
                    </Clipboard>
                  </Box>
                </React.Fragment>
                  ):(<Infotutorial/>)
                }
           
          </Grid>
          {/* MALLA FOOTER 
          <Grid item xs={12}>
            <Item>Footer xs=12</Item>
          </Grid>
          */}
        </Grid>
      </Container>
      </div>
    );
  }
}


export default App;
