import { Component } from "react";
import { AppBar, Box } from '@mui/material';
import { Toolbar } from '@mui/material';
import { Typography } from '@mui/material';
import { IconButton } from '@mui/material';
import { List } from '@mui/icons-material';
import { Menu } from '@mui/material';
import { MenuItem } from '@mui/material';


let Logo = (props) => (
  <div style={{textAlign: 'left'}}>
    <img src={`./images/${props.logo}_w.svg`} alt="logo MP" height={props.altura}/>
  </div>
);

class MyCompanyAppBar extends Component {
  constructor(props) {
    super(props);
    this.state = {
      anchorEl: null,
      valor: "todavia no ha elegido!!!"
    };
  }
  handleClick = event => {
    this.setState({ anchorEl: event.currentTarget });
  };
  handletoClose = event => {
    this.setState({
      anchorEl: null,
    });
  };
  handleClose = event => {
    this.setState({
      anchorEl: null,
      valor: event.currentTarget.childNodes[0].nodeValue
    });
    this.props.logoseleccionado(event.target.childNodes[0].nodeValue);
  };
  
  render() {
    const lista = this.props.listaseleccion.sort(function(a,b){
                                                    var x = a.name.toLowerCase();
                                                    var y = b.name.toLowerCase();
                                                    if (x < y) {return -1;}
                                                    if (x > y) {return 1;}
                                                    return 0;})
                                            .map((elem)=>
      <MenuItem onClick={this.handleClose} key={elem[this.props.keytoiterate].toString()} >{elem[this.props.keytoiterate]}</MenuItem>
    );

    return (
      <Box sx={{ flexGrow: 1, paddingTop: 0 }}>
        <AppBar position="static" style={{ marginBottom: 2}}>
          <Toolbar sx={{backgroundColor:'#BA0C2F'}}>
            <IconButton
            size="large"
            edge="start"
            color="inherit"
            aria-label="menu"
            sx={{ mr: 2 }}
            onClick={this.handleClick}
            >
            <List />
            </IconButton>
            <Menu
              id="simple-menu"
              anchorEl={this.state.anchorEl}
              open={Boolean(this.state.anchorEl)}
              onClose={this.handletoClose}
            >
              {lista}
            </Menu>
            <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
              Selecciona Empresa / Select Company
            </Typography>
            <Logo logo={this.props.pathlogo} altura={50} />
          </Toolbar>
        </AppBar>
      </Box>
    );
  }
}

export default MyCompanyAppBar;