import React, { Component } from "react";

class ListaRedesSociales extends Component{
    constructor(props){
        super(props);
        this.state = null;
    }
    testeaRed (tipo){
        switch (tipo) {
            case 'linkedin': return <img src={`http://media.macpuarsa.es/FIRMAS/MPASCENSORES/2020/images/linkedin.png`} alt="linkedin" width='30px' height='25px'/>;
            case 'twitter': return <img src={`http://media.macpuarsa.es/FIRMAS/MPASCENSORES/2020/images/twitter.png`} alt="twitter" width='30px' height='25px'/>;
            case 'facebook': return <img src={`http://media.macpuarsa.es/FIRMAS/MPASCENSORES/2020/images/facebook.png`} alt="facebook" width='30px' height='25px'/>;
            case 'instagram': return <img src={`http://media.macpuarsa.es/FIRMAS/MPASCENSORES/2020/images/instagram.png`} alt="instagram" width='30px' height='25px'/>;
            case 'youtube': return <img src={`http://media.macpuarsa.es/FIRMAS/MPASCENSORES/2020/images/youtube.png`} alt="youtube" width='30px' height='25px'/>;
            default: return null;
        }
    }
    render() {
        const listaredes = this.props.redesmp.filter((item)=>item.idioma === this.props.idioma);
        const listItems = listaredes.map((item, index) =>
                <a href={item.url} style={{color:'#5B6770', paddingRight:'2px'}} key={item.url} target='_blank'>
                    {this.testeaRed(item.tipored)}
                </a>
        );
        return (
            <React.Fragment>
               {listItems}
            </React.Fragment>
        );
    }
}

export default ListaRedesSociales;