import React, { Component } from 'react';
import { styled } from '@mui/material/styles';
import {Grid, Typography, TextField } from '@mui/material';
import CampoSeleccion from './CampoSeleccion';

const CamposEntrada = styled(TextField)(({theme})=>({
    marginRight: '10px',
    padding:'2px',
    width:'100%',
    '& input':{
      height: '0.5em',
      fontSize: '14px',
    }
  }));

class Muestradatosusuario extends Component {
    constructor(props){
       super(props);
       this.handleChange = this.handleChange.bind(this);
       this.handleSelected = this.handleSelected.bind(this);
    }

    handleChange (evt) {
       this.props.modifDatosPersonales(evt.target);
    }
    handleSelected (evt) {
       this.props.modifDatosDominio(evt);
    }

    render() {
        //Encuentra el objeto del arreglo 'logosMP' que coincide con el nombre del logo
        
        let filtradoLogo = this.props.logosMP.find((element)=>(element.name === this.props.logotipo)); //devuelve el objeto asociado al logo
        const domains = filtradoLogo.emaildomain; //devuelve el objeto de dominios
        const vectorclavesdominios = Object.keys(domains); //Array con las claves: ['se','es','en','fr','de',....]
        const listadoDominios = vectorclavesdominios.map(function(elem){
                                                              return {
                                                                        clave:elem,
                                                                        valor:domains[elem]
                                                                      };
                                                            });

        return (
          <React.Fragment>
            <Grid container item xs={12} spacing={1}>
                <Grid item xs={12} sm={4}>
                  <CamposEntrada id="outlined-basic" name='username' label="Nombre/Name" variant="outlined" onChange={this.handleChange} />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <CamposEntrada id="outlined-basic" name='surname' label="Apellidos/Surnames" variant="outlined" onChange={this.handleChange} />
                </Grid>
                <Grid item xs={12} sm={2}>
                  <CamposEntrada id="outlined-basic" name='extofficephone' label="phone Ext" variant="outlined" onChange={this.handleChange} />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <CamposEntrada id="outlined-basic" name='nativejobtitle' label="JobTitle native/Puesto (esp)" variant="outlined" onChange={this.handleChange} />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <CamposEntrada id="outlined-basic" name='englishjobtitle' label="JobTitle english/Puesto (eng)" variant="outlined" onChange={this.handleChange} />
                </Grid>
                <Grid item xs={12} sm={4}>
                  <CamposEntrada id="outlined-basic" name='mobilephone' label="mobile/movil nº" variant="outlined" onChange={this.handleChange} />
                </Grid>
                <Grid item xs={12} sm={2}>
                  <CamposEntrada id="outlined-basic" name='usermail' label="email" variant="outlined" onChange={this.handleChange} />
                </Grid>
                <Grid item xs={12} sm={1}>
                  <Typography variant='h4' sx={{paddingRight:'10px', color:'#BA0C2F'}}>@</Typography>
                </Grid>
                <Grid item xs={12} sm={5}>
                  <CampoSeleccion listaseleccion={listadoDominios} idioma={this.props.idioma} idiomaseleccionado={this.handleSelected} />
                </Grid>
            </Grid>
        </React.Fragment>
        );
    }
}


export default Muestradatosusuario;